using System;

namespace CacheTower;

/// <summary>
/// Describes where the value returned by a cache read originated.
/// </summary>
[Flags]
public enum CacheValueSource
{
	/// <summary>
	/// The value was generated by the value factory.
	/// </summary>
	Factory = 1,
	/// <summary>
	/// The value was read from the first cache layer.
	/// </summary>
	MemoryLayer = 2,
	/// <summary>
	/// The value was read from a cache layer below the first cache layer.
	/// </summary>
	BackupLayer = 4,
	/// <summary>
	/// The value was fresh according to the cache entry expiry.
	/// </summary>
	Fresh = 8,
	/// <summary>
	/// The value was stale and was returned while a refresh was being performed.
	/// </summary>
	Stale = 16
}

/// <summary>
/// Provides diagnostic information about a cache read without changing its value.
/// </summary>
/// <param name="Source">Where the returned value originated.</param>
/// <param name="LayerIndex">The zero-based index of the layer that supplied the value, or <c>-1</c> for the factory.</param>
/// <param name="Expiry">The expiry of the cache entry that supplied the value, if one was available.</param>
public sealed record CacheReadReceipt(CacheValueSource Source, int LayerIndex, DateTime? Expiry);

/// <summary>
/// Contains the value and receipt for a cache read.
/// </summary>
/// <typeparam name="T">The type of the cached value.</typeparam>
/// <param name="Value">The value returned by the cache read.</param>
/// <param name="Receipt">The source receipt for this read.</param>
public sealed record CacheReadResult<T>(T? Value, CacheReadReceipt Receipt);
